def _generate_cache(self):
        """
        Scan the path for distributions and populate the cache with
        those that are found.
        """
        # NOTE: We don't need to check whether the cache is up-to-date
        #       because the cache is populated at construction time.
        for path in self._paths:
            for dist in self._get_candidate_distributions(path):
                self._cache[dist.key] = dist

